python3 -c 'import itertools,json;P=itertools.product;F=(0,1);A=[("sat",tuple(range(3)),0,lambda a,b:min(2,a+b)),("xor",F,0,lambda a,b:a^b),("or",F,0,lambda a,b:a|b),("and",F,1,lambda a,b:a&b),("union",tuple(range(4)),0,lambda a,b:a|b),("func2",tuple(P(F,repeat=2)),(0,1),lambda a,b:(a[b[0]],a[b[1]])),("I",(0,),0,lambda a,b:0)];I=lambda M:[x for x in M[1] if all(M[3](x,y)==y==M[3](y,x) for y in M[1])];assert all(I(m)==[m[2]] and all(m[3](x,y) in m[1] and all(m[3](m[3](x,y),z)==m[3](x,m[3](y,z)) for z in m[1]) for x in m[1] for y in m[1]) for m in A);H=0;N=0;exec("for m in A:\n for n in A:\n  for seq in P(n[1],repeat=len(m[1])):\n   f=dict(zip(m[1],seq))\n   if f[m[2]]==n[2] and all(f[m[3](a,b)]==n[3](f[a],f[b]) for a in m[1] for b in m[1]):\n    H+=1\n    assert f[I(m)[0]]==I(n)[0]\n");assert all(x!=1-x for x in F);print(json.dumps({"theorem":"unique natural point in Mon","finite_models":len(A),"verified_homomorphisms":H,"G_empty_word_code":1,"unstructured_two_point_swap":"no fixed point","God_identity_proved":False,"all_domains_proved":False},sort_keys=True))' "$@"
